        assert get_numversion_from_version("5") == (5, 0, 0)

    def test_version_with_alpha_characters(self):
        assert get_numversion_from_version("2.0.1b1") == (2, 0, 1)

    def test_version_with_alpha_characters_in_major(self):
        assert get_numversion_from_version("v1.2.3") == (1, 2, 3)

    def test_version_with_multiple_alpha_chars_in_segment(self):
        assert get_numversion_from_version("2.0rc1") == (2, 0, 1)

    def test_version_completely_alpha_segment(self):
        # If a segment has no digits, it defaults to 0
        assert get_numversion_from_version("1.0.beta") == (1, 0, 0)

    def test_version_longer_than_three_segments(self):
        # Should only take the first 3 segments
        assert get_numversion_from_version("1.2.3.4.5") == (1, 2, 3)

    def test_version_with_trailing_dots(self):
        assert get_numversion_from_version("1.2.") == (1, 2, 0)

    def test_version_empty_string_split_parts(self):
        # Handles cases where version parts might be empty due to split
        assert get_numversion_from_version("1..2") == (1, 0, 2)

    def test_combined_prefix_and_alpha(self):
